// Creating unique symbols
const sym1 = Symbol('id');
const sym2 = Symbol('id');
console.log(sym1 === sym2); // false! They are completely unique.

const user = {
  name: 'Alice',
  age: 30,
  [sym1]: 12345 // Using a symbol as an object key
};

// Symbols are hidden from normal iteration
console.log(Object.keys(user)); // ['name', 'age'] (sym1 is hidden!)

// How to access the symbol
console.log(user[sym1]); // 12345

const symbolKeys = Object.getOwnPropertySymbols(user);
console.log(symbolKeys); // [Symbol(id)]
